/* Token Radar dashboard: warm paper, deep ink, teal for value, amber for the watchlist. */
:root {
  --paper: #f6f4ee;
  --card: #fffdf8;
  --ink: #17202b;
  --muted: #5b6672;
  --line: #ddd6c7;
  --teal: #0f766e;
  --teal-dark: #0b5e57;
  --amber: #b45309;
  --amber-soft: #fef3c7;
  --green: #15803d;
  --red: #b91c1c;
  --radius: 12px;
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.skip { position: absolute; left: -9999px; top: 0; background: var(--ink); color: #fff; padding: 8px 12px; }
.skip:focus { left: 8px; top: 8px; z-index: 50; }
.shell { max-width: 1160px; margin: 0 auto; padding: 0 20px 48px; }
.top {
  display: flex; justify-content: space-between; align-items: baseline; gap: 16px;
  padding: 18px 0 12px; border-bottom: 3px solid var(--ink); flex-wrap: wrap;
}
.brand { display: flex; align-items: baseline; gap: 10px; }
.mark { width: 14px; height: 14px; border-radius: 50%; background: var(--teal); display: inline-block; box-shadow: 0 0 0 4px #ccfbf1; }
.brand-name { font: 700 22px/1 Georgia, "Times New Roman", serif; letter-spacing: .02em; }
.brand-sub { color: var(--muted); font-size: 13px; }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.top-meta span { background: var(--card); border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px; font-size: 12px; color: var(--muted); }
.lede { padding: 26px 0 8px; }
.lede h1 { font: 700 34px/1.15 Georgia, "Times New Roman", serif; margin: 0 0 10px; max-width: 760px; }
.lede p { margin: 0; color: #334155; max-width: 760px; font-size: 16px; }
.facts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin: 20px 0 4px; }
.fact { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; }
.fact span { display: block; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.fact b { font: 700 24px/1.2 Georgia, serif; }
.fact small { display: block; color: var(--muted); font-size: 12px; margin-top: 2px; }
.panel { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px 20px; margin: 16px 0; }
.panel h2 { font: 700 20px/1.2 Georgia, serif; margin: 0 0 6px; }
.sub { color: var(--muted); font-size: 13px; }
.formula {
  font: 600 15px/1.6 "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  background: #0f766e; color: #ecfdf5; border-radius: 8px; padding: 12px 14px; margin: 10px 0; overflow-x: auto;
}
table.mini { width: 100%; border-collapse: collapse; font-size: 13px; margin-top: 8px; }
table.mini th, table.mini td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #eee7d6; }
table.mini th { color: var(--muted); font-weight: 600; text-transform: uppercase; font-size: 11px; letter-spacing: .05em; }
table.mini td.num, table.mini th.num { text-align: right; font-variant-numeric: tabular-nums; }
.controls { display: flex; gap: 12px; align-items: flex-end; flex-wrap: wrap; margin: 18px 0 12px; }
.field label, .field .sub { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; text-transform: uppercase; letter-spacing: .05em; }
.field input[type="search"], .field select {
  font: inherit; padding: 9px 10px; border: 1px solid var(--line); border-radius: 8px; background: var(--card); min-width: 220px;
}
.field select { min-width: 180px; }
.tabs { display: flex; gap: 6px; }
.tabs button {
  font: inherit; padding: 9px 14px; border: 1px solid var(--line); border-radius: 999px; background: var(--card); cursor: pointer;
}
.tabs button[aria-pressed="true"] { background: var(--ink); color: #fff; border-color: var(--ink); }
.count { margin-left: auto; color: var(--muted); font-size: 13px; }
.table-wrap { overflow-x: auto; }
table.board { width: 100%; border-collapse: collapse; }
table.board caption { text-align: left; padding-bottom: 8px; }
table.board th, table.board td { padding: 10px 8px; border-bottom: 1px solid #eee7d6; text-align: left; vertical-align: middle; }
table.board th button { font: inherit; font-weight: 600; background: none; border: 0; cursor: pointer; color: var(--ink); padding: 0; }
table.board th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .05em; }
.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.pos { color: var(--green); font-weight: 600; }
.neg { color: var(--red); font-weight: 600; }
.name b { display: block; font-size: 15px; }
.name .sub { display: block; font-size: 12px; }
.badge {
  display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
  border-radius: 999px; padding: 2px 8px; margin-left: 6px; vertical-align: 1px;
}
.badge.watch { background: var(--amber-soft); color: var(--amber); border: 1px solid #fcd34d; }
.badge.early { background: #ecfdf5; color: var(--teal-dark); border: 1px solid #99f6e4; }
.implied .bar { height: 6px; background: #e7e2d3; border-radius: 3px; overflow: hidden; margin-bottom: 4px; }
.implied .bar i { display: block; height: 100%; background: var(--teal); }
.implied .num { font-weight: 700; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #f8f5ec; }
tbody tr[data-selected="true"] { background: #eef7f5; }
.status { font-size: 12px; color: var(--muted); }
.empty { text-align: center; padding: 32px 16px; }
.button { font: inherit; padding: 9px 16px; border-radius: 8px; border: 1px solid var(--ink); background: var(--ink); color: #fff; cursor: pointer; }
.detail { border: 0; border-radius: 16px; padding: 0; width: min(680px, 94vw); max-height: 94vh; overflow: auto; box-shadow: 0 24px 64px rgba(23, 32, 43, .35); }
.detail::backdrop { background: rgba(23, 32, 43, .55); }
.detail-head { display: flex; justify-content: space-between; gap: 16px; padding: 16px 22px 0; align-items: flex-start; }
.detail-head h2 { font: 700 24px/1.2 Georgia, serif; margin: 4px 0 6px; }
.close { font: inherit; padding: 6px 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--card); cursor: pointer; }
.detail-section { padding: 10px 22px 14px; border-top: 1px solid #eee7d6; }
.detail-section h3 { font: 700 16px/1.2 Georgia, serif; margin: 0 0 10px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; }
.equation div { display: flex; justify-content: space-between; border-bottom: 1px dashed var(--line); padding: 4px 0; }
.equation div.total { grid-column: 1 / -1; border-bottom: 0; background: #ecfdf5; border-radius: 8px; padding: 10px 12px; }
.equation span { color: var(--muted); font-size: 13px; }
ol.steps { margin: 0; padding-left: 22px; font-size: 14px; }
ol.steps li { margin: 6px 0; }
ol.steps li b { display: block; font-weight: 600; }
ol.steps .cost { color: var(--muted); font-size: 13px; }
.note { background: var(--amber-soft); border: 1px solid #fcd34d; border-radius: 8px; padding: 8px 12px; font-size: 13px; margin-top: 8px; }
footer.foot { color: var(--muted); font-size: 12px; padding: 8px 0 0; }
@media (max-width: 760px) {
  .facts { grid-template-columns: 1fr 1fr; }
  .lede h1 { font-size: 26px; }
  .equation { grid-template-columns: 1fr; }
  .count { margin-left: 0; }
}
